import { useEffect, useMemo, useRef, useState } from 'react'
import './App.css'
import type { MewayAuthResult } from './discord'
import type { Level, Mission, MissionTask } from './data'

type Page='Главная'|'Миссии'|'Игры'|'Квизы'|'Слова'|'Челленджи'|'Награды'|'Рейтинг'|'Профиль'|'Админ'
type Section='games'|'quizzes'|'words'|'challenges'|'rewards'
